import { RAW_ROUTE_LIST, type RawRouteKey, SANDBOX_ROUTE_NAMES, type SandboxGroup, type SandboxProcedure } from "@intentic/sandbox-contract";
import type { procedures, raw, sockets } from "./daemon";

// Every contract route the fixture daemon leaves unanswered, and why: the demo's real coverage, stated. The demo's
// typecheck holds this list to the contract in both directions. A route the fixture neither serves nor lists here is a
// missing property below, and a listed one that the fixture now serves, or that the contract dropped, is an unknown one.
// So a new route lands with a decision: answer it in daemon.ts, or give it a reason here.

type ContractRoute = { readonly [G in SandboxGroup]: `${G}.${SandboxProcedure<G>}` }[SandboxGroup] | RawRouteKey;
type Procedures = typeof procedures;
type Served = { readonly [G in keyof Procedures]: `${G}.${keyof Procedures[G] & string}` }[keyof Procedures] | keyof typeof raw | keyof typeof sockets;
type Unserved = Exclude<ContractRoute, Served>;

// Out of the demo by design: nothing the editor does reaches these, or they need something a browser tab can't fake.
const NOT_THE_EDITORS = `Not an editor call: the ic CLI, an agent's tools, a paired machine, a listener process, a webhook sender or a CI job makes it.`;
const OFF_SITE = `Answers a visitor's browser on the owner's own site (the web-chat widget, the bug-report intake), never the editor.`;
const ISSUES_INBOX = `The issues inbox: no in-tree view calls it, the vendored issues extension (source outside this repository) may, and the fixture holds no bug reports.`;
const REAL_SIGN_IN = `Real sign-in and access control: the demo's session is seeded, so there is nothing to authenticate, recover or revoke.`;
const REAL_MACHINE = `Acts on real infrastructure (engines, runtime installs, bundles, moving out, paired machines, VPN, network disks, push, speech), and the demo runs on none.`;

// Gaps a visitor can reach: the editor calls these and the fixture doesn't answer them yet. Serving one moves it out.
const UNFILLED_VIEW = `Not simulated yet: a view reads it and gets the demo's 404.`;
const UNSIMULATED_WRITE = `Not simulated yet: a control sends it and gets the demo's 404.`;

